public class QueryNullMatrix62 {
 public static Account pickReturn(String marker) { return [SELECT Id,Name FROM Account WHERE Name=:marker ORDER BY Id] ?? null; }
 public static Account pickInit(String marker) { Account value=[SELECT Id,Name FROM Account WHERE Name=:marker ORDER BY Id] ?? null; return value; }
 public static Account pickAssign(String marker) { Account value; value=[SELECT Id,Name FROM Account WHERE Name=:marker ORDER BY Id] ?? null; return value; }
 public static List<Account> pickList(String marker) { return [SELECT Id,Name FROM Account WHERE Name=:marker ORDER BY Id] ?? null; }
 public static LeadStatus pickStatus() { return [SELECT ApiName FROM LeadStatus WHERE IsConverted=true LIMIT 1] ?? null; }
 public static String observe(String kind,Integer size) {
  Savepoint sp=Database.setSavepoint();
  Map<String,Object> answer=new Map<String,Object>{'kind'=>kind,'rows'=>size,'phase'=>'setup'};
  try {
   String marker='owned-query-null-'+kind+'-'+size;
   Integer collisions=[SELECT COUNT() FROM Account WHERE Name=:marker];
   if(collisions!=0) { answer.put('outcome','collision'); return JSON.serialize(answer); }
   List<Account> seeds=new List<Account>();
   for(Integer i=0;i<size;i++) seeds.add(new Account(Name=marker));
   if(!seeds.isEmpty()) insert seeds;
   answer.put('phase','evaluate');
   if(kind=='list') {
    List<Account> values=pickList(marker);
    answer.put('outcome','returned');answer.put('isNull',values==null);answer.put('count',values==null?null:values.size());
   } else {
    Account value;
    if(kind=='return') value=pickReturn(marker);
    else if(kind=='initialize') value=pickInit(marker);
    else value=pickAssign(marker);
    answer.put('outcome','returned');answer.put('isNull',value==null);
    answer.put('sameId',value!=null&&seeds.size()==1&&value.Id==seeds[0].Id);
    answer.put('sameName',value!=null&&value.Name==marker);
   }
  } catch(Exception error) {answer.put('outcome','exception');answer.put('exType',error.getTypeName());answer.put('exMessage',error.getMessage());}
  finally { Database.rollback(sp); }
  return JSON.serialize(answer);
 }
}

